@namespace CheckoutWizard.Components

<div class="checkout-wizard">
    <h2>Checkout — Step @(_step + 1) of 2</h2>

    @if (_step == 0)
    {
        <ShippingStep Shipping="_order.Shipping" OnNext="HandleShippingComplete" />
    }
    else
    {
        <PaymentStep Payment="_order.Payment"
                     OnBack="HandleBack"
                     OnPlaceOrder="HandlePlaceOrder" />
    }
</div>

@code {
    /// <summary>Raised when the user places the order with all info collected.</summary>
    [Parameter] public EventCallback<Order> OnOrderPlaced { get; set; }

    private readonly Order _order = new();
    private int _step;

    private void HandleShippingComplete()
    {
        _step = 1;
    }

    private void HandleBack()
    {
        _step = 0;
    }

    private async Task HandlePlaceOrder()
    {
        await OnOrderPlaced.InvokeAsync(_order);
    }
}

@namespace CheckoutWizard.Components
@implements IDisposable
@inject IAddressValidator AddressValidator

<fieldset disabled="@_isValidating">
    <legend>Shipping Information</legend>

    <label>
        Name
        <input @bind="Shipping.Name" @bind:event="oninput" />
    </label>

    <label>
        Address
        <input @bind="Shipping.Address" @bind:event="oninput" />
    </label>

    <label>
        City
        <input @bind="Shipping.City" @bind:event="oninput" />
    </label>

    <label>
        Zip Code
        <input @bind="Shipping.ZipCode" @bind:event="oninput" />
    </label>
</fieldset>

@if (!string.IsNullOrEmpty(_errorMessage))
{
    <p class="validation-error" role="alert">@_errorMessage</p>
}

<button disabled="@_isValidating" @onclick="ValidateAndProceed">
    @if (_isValidating)
    {
        <span class="spinner" aria-hidden="true"></span>
        @:Validating…
    }
    else
    {
        @:Next
    }
</button>

@code {
    [Parameter] public ShippingInfo Shipping { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }

    private CancellationTokenSource? _cts;
    private bool _isValidating;
    private string? _errorMessage;

    private async Task ValidateAndProceed()
    {
        _errorMessage = null;

        if (string.IsNullOrWhiteSpace(Shipping.Name)
            || string.IsNullOrWhiteSpace(Shipping.Address)
            || string.IsNullOrWhiteSpace(Shipping.City)
            || string.IsNullOrWhiteSpace(Shipping.ZipCode))
        {
            _errorMessage = "All shipping fields are required.";
            return;
        }

        // Cancel any in-flight validation (e.g. user went back and changed fields).
        CancelPendingValidation();

        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        _isValidating = true;

        try
        {
            var isValid = await AddressValidator.ValidateAddressAsync(
                Shipping.Address, Shipping.City, Shipping.ZipCode, token);

            token.ThrowIfCancellationRequested();

            if (isValid)
            {
                await OnNext.InvokeAsync();
            }
            else
            {
                _errorMessage = "The address could not be verified. Please check and try again.";
            }
        }
        catch (OperationCanceledException)
        {
            // Validation was cancelled — nothing to do.
        }
        finally
        {
            _isValidating = false;
        }
    }

    private void CancelPendingValidation()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }

    public void Dispose()
    {
        CancelPendingValidation();
    }
}

