toolArgs.file_text:
@namespace CheckoutWizard.Components

<fieldset>
    <legend>Payment Information</legend>

    <label>
        Card Number
        <input @bind="Payment.CardNumber" @bind:event="oninput" />
    </label>

    <label>
        Expiry Date
        <input @bind="Payment.ExpiryDate" @bind:event="oninput" placeholder="MM/YY" />
    </label>
</fieldset>

@if (!string.IsNullOrEmpty(_errorMessage))
{
    <p class="validation-error" role="alert">@_errorMessage</p>
}

<div class="button-group">
    <button @onclick="OnBack">Back</button>
    <button @onclick="PlaceOrder">Place Order</button>
</div>

@code {
    [Parameter] public PaymentInfo Payment { get; set; } = default!;
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnPlaceOrder { get; set; }

    private string? _errorMessage;

    private async Task PlaceOrder()
    {
        _errorMessage = null;

        if (string.IsNullOrWhiteSpace(Payment.CardNumber)
            || string.IsNullOrWhiteSpace(Payment.ExpiryDate))
        {
            _errorMessage = "Card number and expiry date are required.";
            return;
        }

        await OnPlaceOrder.InvokeAsync();
    }
}
